/**
 * plugin-pins.ts
 *
 * The agent plugin version this CLI release installs, per plugin platform,
 * with the sha256 of its published bundle. The CLI never follows `latest`
 * on its own; `--plugin-version` asks for another version.
 *
 * Generated by scripts/refresh-plugin-pins.mjs from
 * https://downloads.omnodex.com/plugins/latest.json. Do not edit by hand.
 */

